    c0, c1 = min(c for r, c in zero_cells), max(c for r, c in zero_cells)
    # Find the patterned rectangle with matching dimensions, and reflect its rows horizontally.
    for sr in range(h - (r1-r0+1) + 1):
        for sc in range(w - (c1-c0+1) + 1):
            block = [grid[sr+i][sc:sc+(c1-c0+1)] for i in range(r1-r0+1)]
